SELECT DISTINCTROW qrypassiveElemente.[Element Nr], qrypassiveElemente.Elektrolyseur, qrypassiveElemente.Position, qrypassiveElemente.Generation, qrypassiveElemente.[Anoden Nr], qrypassiveElemente.[Kathoden Nr], qrypassiveElemente.[Membran Nr], qrypassiveElemente.Membrantyp, qrypassiveElemente.Gruppe, qrypassiveElemente.[Einschalt Datum], qrypassiveElemente.[Ausschalt Datum], [Ausschalt Datum]-[Einschalt Datum] AS GesamtDOL, IIf(IsNull([Ausschalt Datum]),Date()-[Einschalt Datum],Null) AS AktuelleDOL, qrypassiveElemente.Abschaltgrund, qrypassiveElemente.[Anode Coating], qrypassiveElemente.[Anode Electrode], qrypassiveElemente.[Anode Shell], qrypassiveElemente.[Cathode Coating], qrypassiveElemente.[Cathode Electrode], qrypassiveElemente.[Cathode Shell], qrypassiveElemente.[Info Membrane], qrypassiveElemente.Remarks, qrypassiveElemente.[Montage Datum], qrypassiveElemente.[Demontage Datum], qrypassiveElemente.[Elektroden Abstand]
FROM qrypassiveElemente
WHERE (((qrypassiveElemente.[Kathoden Nr]) In (SELECT [Kathoden Nr] FROM [qrypassiveElemente] As Tmp GROUP BY [Kathoden Nr] HAVING Count(*)>1 )))
ORDER BY qrypassiveElemente.[Kathoden Nr];
